from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = [[False]*w for _ in range(h)]
    out = [row[:] for row in grid]
    for i in range(h):
        for j in range(w):
            if seen[i][j]:
                continue
            comp = [(i, j)]
            seen[i][j] = True
            q = deque([(i, j)])
            touches = False
            while q:
                r, c = q.popleft()
                if r in (0, h-1) or c in (0, w-1):
                    touches = True
                for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < h and 0 <= nc < w and not seen[nr][nc] and grid[nr][nc] == grid[i][j]:
                        seen[nr][nc] = True
                        comp.append((nr, nc))
                        q.append((nr, nc))
            if not touches:
                for r, c in comp:
                    out[r][c] = 4
    return out
